             rng.below(0x7FFFFFFF));
// R776: the mounted-combat site - the
// R403 mount layer charges the engine:
// the Character carries a mount and
// the combat open reads it (the
// mounted resolution).
int mountedRiders = 0;
for (const auto& c : party.members)
    if (c.hp > 0 && c.mountKind)
        ++mountedRiders;
